  ('Q3', 3, 'In light of recent developments in Jordan-Syria relations, should an opportunity arise to revise the current Yarmouk Agreement, what key modifications would you recommend?', 'في ضوء التطورات الأخيرة في العلاقات الأردنية السورية، وفي حال أُتيحت الفرصة لتعديل اتفاقية اليرموك الحالية، ما هي التعديلات الأساسية التي توصي بها؟', FALSE, NULL::nationality_type[]),
  ('Q4', 4, 'The 1987 Agreement focuses entirely on water allocation and does not address environmental protection in any form — such as environmental impact assessment, minimum ecological flows, or water quality standards. How has this absence shaped the environmental condition of the Yarmouk basin over the past four decades — and what specific environmental provisions would you consider essential in any future agreement?', 'تركّز اتفاقية 1987 بالكامل على تخصيص المياه ولا تتناول حماية البيئة بأي شكل — كتقييم الأثر البيئي أو الحد الأدنى للتدفقات البيئية أو معايير جودة المياه. كيف أثّر هذا الغياب على الوضع البيئي لحوض اليرموك خلال العقود الأربعة الماضية — وما هي الأحكام البيئية المحددة التي تعتبرها ضرورية في أي اتفاقية مستقبلية؟', FALSE, NULL::nationality_type[]),
  ('Q5', 5, 'From your fieldwork and community engagement, what environmental changes have local residents and farmers reported in the Yarmouk basin — and how do these on-the-ground observations compare with official assessments of the basin''s environmental condition?', 'من خلال عملكم الميداني وتواصلكم مع المجتمعات المحلية، ما هي التغيرات البيئية التي أبلغ عنها السكان المحليون والمزارعون في حوض اليرموك — وكيف تقارن هذه الملاحظات الميدانية مع التقييمات الرسمية للوضع البيئي في الحوض؟', FALSE, NULL::nationality_type[]),
  ('Q6', 6, 'How are local communities along the Yarmouk affected by the decline in river flow, and what coping mechanisms have emerged?', 'كيف تتأثر المجتمعات المحلية على طول اليرموك بانخفاض تدفق النهر، وما هي آليات التكيف التي ظهرت؟', FALSE, NULL::nationality_type[]),
  ('Q7', 7, 'Are civil society organizations consulted or involved in any way in decisions about water sharing or the implementation of the 1987 Agreement?', 'هل تتم استشارة منظمات المجتمع المدني أو إشراكها بأي شكل في القرارات المتعلقة بتقاسم المياه أو تنفيذ اتفاقية 1987؟', FALSE, NULL::nationality_type[]),
  ('Q8', 8, 'What role should civil society and environmental organizations play in monitoring and enforcing environmental provisions in any future Yarmouk agreement — and are there examples from other basins where NGO involvement improved environmental outcomes?', 'ما هو الدور الذي ينبغي أن تلعبه منظمات المجتمع المدني والمنظمات البيئية في رصد وإنفاذ الأحكام البيئية في أي اتفاقية مستقبلية لليرموك — وهل هناك أمثلة من أحواض أخرى أدى فيها إشراك المنظمات غير الحكومية إلى تحسين النتائج البيئية؟', FALSE, NULL::nationality_type[]),
  ('Q9', 9, 'Is there anything else you would like to share regarding the 1987 Agreement, the environmental status of the Yarmouk basin, or the future of transboundary cooperation?', 'هل هناك أي شيء آخر تودّ مشاركته بخصوص اتفاقية 1987، أو الوضع البيئي لحوض اليرموك، أو مستقبل التعاون العابر للحدود؟', FALSE, NULL::nationality_type[]),
  ('F1', 10, 'Were any questions unclear or difficult to understand?', 'هل كانت أي من الأسئلة غير واضحة أو صعبة الفهم؟', TRUE, NULL::nationality_type[]),
  ('F2', 11, 'Were any questions too long?', 'هل كانت أي من الأسئلة طويلة جداً؟', TRUE, NULL::nationality_type[]),
  ('F3', 12, 'Was any important topic missing from the questions?', 'هل كان هناك أي موضوع مهم مفقود من الأسئلة؟', TRUE, NULL::nationality_type[]),
  ('F4', 13, 'How long did it take you to complete all questions?', 'كم من الوقت استغرقت للإجابة على جميع الأسئلة؟', TRUE, NULL::nationality_type[])
) AS d(question_code, order_index, text_en, text_ar, is_feedback, visible_nationalities);
